int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;
    struct transaction_t *t;
    int ret = 0;

    if (!buffer_journalled(bh))
        return 0;

    jh = journal_grab_journal_head(bh);
    if (!jh)
        return -EINVAL;

    spin_lock(&journal->j_list_lock);

    if (jh->b_jlist == BJ_None) {
        jh->b_jlist = BJ_Forget;
        jh->b_modified = 0;
        jh->b_next = NULL;
        jh->b_prev = NULL;
        clear_buffer_dirty(bh);
        spin_unlock(&journal->j_list_lock);
        journal_release_journal_head(jh);
        return 0;
    }

    t = jh->b_transaction;
    if (t && t->t_state == T_Cancel) {
        jh->b_jlist = BJ_Forget;
        jh->b_modified = 0;
        jh->b_next = NULL;
        jh->b_prev = NULL;
        clear_buffer_dirty(bh);
        spin_unlock(&journal->j_list_lock);
        journal_release_journal_head(jh);
        return 0;
    }

    if (t && t == journal->j_running_transaction) {
        jh->b_modified = 0;
        jh->b_next = NULL;
        jh->b_prev = NULL;
        clear_buffer_dirty(bh);
        spin_unlock(&journal->j_list_lock);
        journal_release_journal_head(jh);
        return 0;
    }

    if (t && t->t_state == T_Commit && !list_empty(&jh->b_list)) {
        list_del_init(&jh->b_list);
        jh->b_modified = 0;
        jh->b_transaction = NULL;
        jh->b_jlist = BJ_None;
        jh->b_next = NULL;
        jh->b_prev = NULL;
        clear_buffer_dirty(bh);
        spin_unlock(&journal->j_list_lock);
        journal_release_journal_head(jh);
        return 0;
    }

    jh->b_jlist = BJ_Forget;
    jh->b_modified = 0;
    jh->b_next = NULL;
    jh->b_prev = NULL;
    clear_buffer_dirty(bh);
    spin_unlock(&journal->j_list_lock);
    journal_release_journal_head(jh);
    return 0;
}

int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;
    transaction_t *t;

    if (!buffer_journalled(bh))
        return 0;

    jh = journal_grab_journal_head(bh);
    if (!jh)
        return -EINVAL;

    spin_lock(&journal->j_list_lock);
    t = jh->b_transaction;

    if (t && t != journal->j_running_transaction) {
        jh->b_bhs = NULL;
        jh->b_next = NULL;
        jh->b_modified = 0;
        jh->b_transaction = NULL;
        jh->b_jlist = 0;
        clear_bit(BH_Journaled, &bh->b_state);
        spin_unlock(&journal->j_list_lock);
        journal_put_journal_head(jh);
        return 0;
    }

    if (t == journal->j_running_transaction) {
        spin_unlock(&journal->j_list_lock);
        journal_put_journal_head(jh);
        return 0;
    }

    jh->b_modified = 0;
    jh->b_transaction = NULL;
    jh->b_jlist = 0;
    clear_bit(BH_Journaled, &bh->b_state);
    spin_unlock(&journal->j_list_lock);
    journal_put_journal_head(jh);
    return 0;
}

int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;
    int ret = 0;

    if (!buffer_journaled(bh))
        return 0;

    jh = journal_grab_journal_head(bh);

    if (jh->b_transaction == journal->j_running_transaction) {
        if (jh->b_modified) {
            jh->b_modified = 0;
            journal->j_running_transaction->t_modified_buffers--;
        }
        jh->b_transaction = NULL;
        jh->b_jlist = 0;
    } else if (jh->b_transaction) {
        if (jh->b_modified)
            jh->b_modified = 0;

        jh->b_transaction = NULL;
        jh->b_jlist = 0;
    } else {
        jh->b_modified = 0;
        jh->b_jlist = 0;
    }

    jbd_debug(6, "unmap buffer %p jh %p\n", bh, jh);
    journal_put_journal_head(jh);

    return ret;
}

int journal_unmap_buffer(journal_t *journal, struct buffer_head *bh) {
    struct journal_head *jh;

    if (!buffer_journalled(bh))
        return 0;

    jh = journal_get_jhead(journal, bh->b_blocknr);
    if (!jh)
        return -EINVAL;

    jbd_lock_jh(jh);
    if (jh->b_transaction) {
        if (jh->b_transaction == journal->j_running_transaction) {
            jbd_unlock_jh(jh);
            journal_put_jhead(journal, jh);
            return 1;
        }
        jbd_lock_t();
        jh->b_transaction = NULL;
        jbd_unlock_t();
    }

    if (buffer_dirty(bh)) {
        bh->b_dirty = 0;
        journal_clean_buffer(bh);
    }

    jbd_unlock_jh(jh);
    journal_put_jhead(journal, jh);
    return 0;
}
